	private JSONArray pagination(JSONArray jsonArray, int limit, int offset) {
		diagnostic.prepareDebug("==========> GetNewsDetailsMockPostProcessor Mock - pagination:: Begin ").log();
		JSONArray paginationJSON = new JSONArray();

		int j = 0;
		for (int i = offset; i < jsonArray.length(); i++) {
			if (j == limit) {
				break;
			} else {
				paginationJSON.put(jsonArray.get(i));
			}
			j++;
		}
		diagnostic.prepareDebug("==========> GetNewsDetailsMockPostProcessor Mock - pagination:: End ").log();
		return paginationJSON;
	}

